Contract ProcessSaleService::enterItem(barcode:Integer,quantity:Integer): Boolean {
          definition:
          item:Item = Item.allInstance()->any(o | o.Barcode = barcode)

            precondition:
          CurrentSale.oclIsUndefined() = false and CurrentSale.IsComplete = false and item.oclIsUndefined() = false and item.StockNumber > 0

            postcondition:
          { let saleLine:SalesLineItem in saleLine.oclIsNew() and CurrentSale.ContainedSalesLine->includes(saleLine) and saleLine.Quantity = quantity and saleLine.Subamount = item.Price * quantity and item.StockNumber = item.StockNumber - quantity and ThirdPartyServices.saveSaleLine(saleLine) and result = true }

        }

